                    .join("Artist")
                    .join("Album")
                    .join("keep-me.flac")
            )
            .unwrap(),
            b"moves",
            "an entry with no collision still leaves the legacy tree"
        );
        assert_eq!(report.left_in_place.len(), 1, "got {report:?}");
