/// True when `path` carries positive evidence of being a legacy album
/// directory: a file at its top level, or a disc folder. The stager nests at
/// most one disc level inside an album directory, so a tree with no file and no
/// disc folder is indistinguishable from an artist level and must not be
/// renamed.
fn looks_like_a_legacy_album(path: &Path) -> bool {
    let Ok(entries) = std::fs::read_dir(path) else {
        return false;
    };
    entries.flatten().any(|entry| {
        if entry.file_type().map(|kind| kind.is_dir()).unwrap_or(false) {
