/// True when `path` is, or lies inside, `root`. Both sides are canonicalised, so
/// a symlinked or `.`-containing spelling of either still matches.
fn is_inside(root: &Path, path: &Path) -> bool {
    match (
        std::fs::canonicalize(root),
        std::fs::canonicalize(path),
    ) {
        (Ok(root), Ok(path)) => path == root || path.starts_with(root),
        _ => false,
    }
}

